const $ = s => document.querySelector(s);
const state = {token:localStorage.getItem('rm_token')||'',user:JSON.parse(localStorage.getItem('rm_user')||'null'),page:'home',cache:{},rideType:'POOL',selectedBooking:null,rating:5};
const icons={home:'⌂',book:'＋',rides:'⇄',subscription:'◈',profile:'◎',safety:'♡',driver:'▰',earnings:'₹',ratings:'☆',admin:'▦',users:'♙',verify:'✓',nodes:'⌖',support:'☏',sos:'⚠',reports:'▥',settings:'⚙',payments:'₹'};
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(n){return '₹'+Number(n||0).toLocaleString('en-IN');}
function dateTime(s){if(!s)return '—';return new Date(s).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});}
function dateInput(s){const d=s?new Date(s):new Date(Date.now()+3600000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function statusPill(s){const x=String(s||'unknown');let c='';if(/approved|completed|active|paid|resolved/i.test(x))c='green';else if(/pending|requested|en_route|progress/i.test(x))c='amber';else if(/cancel|reject|open|rejected/i.test(x))c='red';else c='blue';return `<span class="pill ${c}">${esc(x.replaceAll('_',' ').toLowerCase().replace(/^\w/,m=>m.toUpperCase()))}</span>`;}
function toast(msg){const t=$('#toast');t.className='toast';t.textContent=msg;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.className='',3800);}
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const res=await fetch('/api'+path,{...opts,headers,body:opts.body&&typeof opts.body!=='string'?JSON.stringify(opts.body):opts.body});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||data.message||`Request failed (${res.status})`);return data;}
function setSession(data){state.token=data.token;state.user=data.user;localStorage.setItem('rm_token',state.token);localStorage.setItem('rm_user',JSON.stringify(state.user));}
function logout(){state.token='';state.user=null;localStorage.removeItem('rm_token');localStorage.removeItem('rm_user');renderAuth();}
function renderAuth(mode='login'){state.page='auth';$('#app').innerHTML=`<div class="auth-wrap"><section class="auth-hero"><div class="brand"><div class="brand-mark">R</div><div>Ride Mate<small>CONNECTING JOURNEYS</small></div></div><h1>Every journey is better when shared.</h1><p>Affordable, safer and eco-friendly daily commuting through trusted people and fixed pick-up points.</p><div class="hero-features"><span>Verified riders and drivers</span><span>Transparent fares, no surge pricing</span><span>Trusted contacts and SOS support</span></div></section><section class="auth-form-side"><form class="auth-form" id="authForm"><div class="brand"><div class="brand-mark small">R</div><div>Ride Mate<small>BHARUCH PILOT</small></div></div><div style="height:30px"></div><h2>${mode==='signup'?'Create your account':mode==='forgot'?'Reset your password':'Welcome back'}</h2><p>${mode==='signup'?'Join your community and make daily travel easier.':mode==='forgot'?'Start the password reset process.':'Sign in to continue your journey.'}</p><div id="authError"></div>${mode==='signup'?`<div class="field"><label>Full name</label><input name="name" required placeholder="Your name" autocomplete="name"></div><div class="field"><label>I want to join as</label><select name="role"><option value="rider">Rider / Passenger</option><option value="driver">Driver</option></select></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" placeholder="you@example.com" ${mode==='forgot'?'':'required'} autocomplete="email"></div>${mode==='signup'?'<div class="field"><label>Phone number (+91)</label><input name="phone" placeholder="+91 98765 43210" required></div>':''}${mode!=='forgot'?'<div class="field"><label>Password</label><input name="password" type="password" required minlength="8" placeholder="At least 8 characters" autocomplete="current-password"></div>':''}<button class="btn primary" style="width:100%;margin-top:5px" type="submit">${mode==='signup'?'Create account':mode==='forgot'?'Get reset code':'Sign in'} →</button>${mode==='login'?'<div style="text-align:right;margin-top:15px"><button class="link-button" type="button" id="forgotBtn">Forgot password?</button></div>':''}<div class="auth-switch">${mode==='signup'?'Already have an account?':mode==='forgot'?'Remembered your password?':'New to Ride Mate?'} <button class="link-button" type="button" id="switchAuth">${mode==='signup'?'Sign in':mode==='forgot'?'Sign in':'Create account'}</button></div><div class="separator"></div><div class="alert info"><b>Demo access</b><br>Rider: rider@ridemate.demo / RideMate123!<br>Driver: driver@ridemate.demo / RideMate123!<br>Admin: admin@ridemate.demo / Admin123!</div><div class="footer-note">Demo environment only. Real OTP, maps, payment processing and emergency dispatch need provider configuration.</div></form></section></div>`;
$('#switchAuth').onclick=()=>renderAuth(mode==='signup'?'login':'signup');if($('#forgotBtn'))$('#forgotBtn').onclick=()=>renderAuth('forgot');$('#authForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),body=Object.fromEntries(fd.entries());try{if(mode==='forgot'){const d=await api('/auth/forgot-password',{method:'POST',body});$('#authError').innerHTML=`<div class="alert info">${esc(d.message)}${d.demoCode?`<br><b>Demo code: ${esc(d.demoCode)}</b>`:''}</div><form id="resetForm"><div class="field"><label>Reset code</label><input name="code" required value="${esc(d.demoCode||'')}"></div><div class="field"><label>New password</label><input name="newPassword" type="password" minlength="8" required placeholder="At least 8 characters"></div><button class="btn primary" style="width:100%">Reset password</button></form>`;$('#resetForm').onsubmit=async ev=>{ev.preventDefault();const reset=Object.fromEntries(new FormData(ev.currentTarget).entries());try{const out=await api('/auth/reset-password',{method:'POST',body:{email:body.email,code:reset.code,newPassword:reset.newPassword}});$('#authError').innerHTML=`<div class="alert info">${esc(out.message)}</div>`;setTimeout(()=>renderAuth('login'),1000)}catch(err){$('#authError').insertAdjacentHTML('beforeend',`<div class="alert danger">${esc(err.message)}</div>`)}};return;}const d=await api(mode==='signup'?'/auth/signup':'/auth/login',{method:'POST',body});setSession(d);renderApp();}catch(err){$('#authError').innerHTML=`<div class="alert danger">${esc(err.message)}</div>`;}};}
const riderNav=[['home','Overview'],['book','Book a ride'],['rides','My rides'],['subscription','Subscriptions'],['profile','My profile'],['safety','Safety & help']];const driverNav=[['home','Overview'],['driver','Available rides'],['rides','My rides'],['earnings','Earnings'],['ratings','Ratings & feedback'],['subscription','Subscriptions'],['profile','My profile'],['safety','Safety & help']];const adminNav=[['home','Overview'],['users','User management'],['verify','Verification'],['rides','Ride monitoring'],['nodes','Nodal points'],['payments','Payments'],['support','Support tickets'],['sos','SOS alerts'],['reports','Reports & analytics']];
function renderShell(){const nav=state.user.role==='admin'?adminNav:state.user.role==='driver'?driverNav:riderNav;$('#app').innerHTML=`<div class="shell"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="btn secondary mobile-menu" id="menuBtn">☰</button><div class="brand"><div class="brand-mark small">R</div><div>Ride Mate<small>CONNECTING JOURNEYS</small></div></div></div><div class="top-actions"><button class="btn secondary small" id="notifBtn">♧ <span class="hide-mobile">Notifications</span></button><div class="user-chip"><div class="avatar">${esc((state.user.name||'U')[0].toUpperCase())}</div><div class="user-name"><b>${esc(state.user.name)}</b><div class="muted" style="font-size:11px;text-transform:capitalize">${esc(state.user.role)}</div></div></div><button class="btn secondary small" id="logoutBtn">Sign out</button></div></header><div class="layout"><aside class="sidebar" id="sidebar"><div class="nav-label">WORKSPACE</div><nav class="nav">${nav.map(([id,label])=>`<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-icon">${icons[id]||'•'}</span>${label}</button>`).join('')}</nav><div class="sidebar-foot"><b>Ride Mate safety</b><br>Meet at verified nodal points. Check vehicle details before boarding.<br><button class="link-button" data-page="safety" style="margin-top:8px">View safety tips →</button></div></aside><main class="main" id="main"></main></div></div>`;
$('#logoutBtn').onclick=logout;$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#notifBtn').onclick=()=>navigate('notifications');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));}
function navigate(page){state.page=page;renderShell();renderPage();}
function head(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${state.user.role==='admin'?'ADMIN CONSOLE':state.user.role==='driver'?'DRIVER WORKSPACE':'RIDER WORKSPACE'}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function stat(label,value,icon,foot='') {return `<div class="card"><div class="stat-icon">${icon}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function empty(icon,title,desc){return `<div class="empty"><div class="empty-icon">${icon}</div><b>${title}</b><p>${desc}</p></div>`;}
function nodeName(id){return (state.cache.nodes||[]).find(n=>n.id===id)?.name||id||'—';}
function rideCard(p,options={}){const d=p.driver||{};const v=p.vehicle||{};return `<div class="ride-card"><div class="ride-top"><div><b>${esc(d.name||'Driver')}</b> ${d.verifiedStatus==='approved'?'<span class="pill green">✓ Verified</span>':''}<div class="muted" style="font-size:11px;margin-top:5px">★ ${Number(d.ratingAvg||0).toFixed(1)} · ${esc(v.model||'Vehicle details pending')} · ${esc(v.number||'')}</div></div><span class="pill blue">${esc(p.rideType||'POOL')}</span></div><div class="route"><div class="route-track"><span></span><i></i><span></span></div><div><div><strong>${esc(nodeName(p.originNodeId))}</strong><small>${dateTime(p.departureTime)}</small></div><div style="margin-top:13px"><strong>${esc(nodeName(p.destNodeId))}</strong><small>Destination nodal point</small></div></div></div><div class="ride-meta"><span>♙ ${p.seatsAvailable} seat(s) left</span><span>◷ approx. ${Math.max(8,Math.round((p.farePerSeat||35)/5))} min</span><span>✓ No surge pricing</span></div><div class="ride-bottom"><div class="fare">${money(p.farePerSeat)} <small>/ seat</small></div>${options.action||''}</div></div>`;}
async function renderPage(){const main=$('#main');main.innerHTML='<div class="card">Loading workspace…</div>';try{const d=await api('/me');state.user=d.user;state.cache.subscription=d.subscription;state.cache.hasSub=d.hasActiveSubscription;state.cache.nodes=await api('/nodal-points');if(state.user.role==='admin')return await renderAdminPage();if(state.user.role==='driver')return await renderDriverPage();return await renderRiderPage();}catch(e){main.innerHTML=`<div class="card"><div class="alert danger">${esc(e.message)}</div><button class="btn primary" onclick="location.reload()">Reload</button></div>`;}}
async function renderRiderPage(){const main=$('#main'),page=state.page;const bookings=await api('/bookings/mine');if(page==='home'){const available=await api('/rides/available');main.innerHTML=head(`Welcome, ${esc(state.user.name.split(' ')[0])} 👋`,'Your next journey starts here. Find a verified ride and share the road.')+`<div class="grid stats">${stat('Active bookings',bookings.filter(b=>['REQUESTED','ACCEPTED','DRIVER_EN_ROUTE','STARTED'].includes(b.status)).length,'⇄','Your upcoming journeys')}${stat('Completed rides',bookings.filter(b=>b.status==='COMPLETED').length,'✓','Ride history')}${stat('Your rating',Number(state.user.ratingAvg||0).toFixed(1)+' ★','☆','Community feedback')}${stat('Subscription',state.cache.hasSub?'Active':'Inactive','◈',state.cache.hasSub?'Access enabled':'Subscribe to book')}</div><div class="quick-actions"><button class="quick" data-page="book"><span>＋</span>Book a ride</button><button class="quick" data-page="rides"><span>⇄</span>View my rides</button><button class="quick" data-page="safety"><span>♡</span>Emergency help</button><button class="quick" data-page="profile"><span>⚙</span>Settings</button></div><div class="grid two section-gap"><div class="card"><div class="card-head"><h2>Nearby ride options</h2><button class="link-button" data-page="book">See all →</button></div>${available.slice(0,2).map(p=>rideCard(p,{action:`<button class="btn primary small" data-book="${p.id}">Request ride</button>`})).join('')||empty('🚗','No rides posted yet','Try again later or check another route.')}</div><div class="card"><div class="card-head"><h2>Your recent journeys</h2><button class="link-button" data-page="rides">View all →</button></div>${bookings.slice(0,4).map(b=>`<div class="list-row"><div><b>${esc(nodeName(b.pickupNodeId))} → ${esc(nodeName(b.dropNodeId))}</b><p>${dateTime(b.createdAt)} · ${money(b.agreedFare)}</p></div>${statusPill(b.status)}</div>`).join('')||empty('🧭','Your rides appear here','Book a ride to get started.')}</div></div>`;wirePageButtons();return;}
if(page==='book'){const available=await api('/rides/available');main.innerHTML=head('Book a ride','Choose your nodal points, compare transparent fares and request a verified driver.')+(!state.cache.hasSub?'<div class="alert">An active rider subscription is required to book. <button class="link-button" data-page="subscription">View plans →</button></div>':'')+`<div class="grid two"><section class="card"><div class="card-head"><h2>Where are you going?</h2><span class="pill blue">Bharuch pilot</span></div><form id="searchRides"><div class="field"><label>Pick-up nodal point</label><select name="originNodeId" required>${state.cache.nodes.map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('')}</select></div><div class="field"><label>Drop-off nodal point</label><select name="destNodeId" required>${state.cache.nodes.slice().reverse().map(n=>`<option value="${n.id}" ${n.id==='node-2'?'selected':''}>${esc(n.name)}</option>`).join('')}</select></div><div class="field"><label>Ride type</label><div class="form-row"><label class="btn ${state.rideType==='POOL'?'soft':'secondary'}"><input type="radio" name="rideType" value="POOL" ${state.rideType==='POOL'?'checked':''}> Pool · share cost</label><label class="btn ${state.rideType==='SOLO'?'soft':'secondary'}"><input type="radio" name="rideType" value="SOLO" ${state.rideType==='SOLO'?'checked':''}> Solo · privacy</label></div></div><div class="map-panel"><div class="map-inner"><b>Suggested nodal points</b><p style="font-size:12px;margin:6px 0">Fixed, curated pickup and drop-off hubs make trips easier to coordinate.</p><div class="map-pin">📍 <div><b>Meet at a verified point</b><small>Map provider not connected · schematic preview</small></div></div></div></div><button class="btn primary" style="width:100%;margin-top:16px">Find matching rides →</button></form></section><section class="card"><div class="card-head"><h2>Available rides</h2><span class="pill">${available.length} options</span></div><div id="availableList">${available.map(p=>rideCard(p,{action:`<button class="btn primary small" data-book="${p.id}" ${!state.cache.hasSub?'disabled':''}>Request</button>`})).join('')||empty('🚘','No matching rides','Drivers can post routes from the Driver workspace.')}</div><div class="footer-note">Fare is shown per seat. Final fare is confirmed before booking. No per-ride platform commission.</div></section></div>`;$('#searchRides').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.rideType=f.get('rideType');const p=new URLSearchParams({originNodeId:f.get('originNodeId'),destNodeId:f.get('destNodeId')});const list=await api('/rides/available?'+p);$('#availableList').innerHTML=list.map(x=>rideCard(x,{action:`<button class="btn primary small" data-book="${x.id}" ${!state.cache.hasSub?'disabled':''}>Request</button>`})).join('')||empty('🚘','No matching rides','Try another nodal-point pair.');wirePageButtons();};wirePageButtons();return;}
if(page==='rides'){main.innerHTML=head('My rides','Track your requests, active journeys and past fare receipts.')+`<div class="card"><div class="card-head"><h2>Ride history</h2><span class="pill">${bookings.length} total</span></div>${bookings.map(b=>`<div class="list-row"><div><b>${esc(nodeName(b.pickupNodeId))} → ${esc(nodeName(b.dropNodeId))}</b><p>${dateTime(b.createdAt)} · Driver: ${esc(b.driver?.name||'—')} · ${money(b.agreedFare)}</p><p class="muted">Vehicle: ${esc(b.vehicle?.number||'—')} · Payment: ${esc(b.paymentStatus||'PENDING')}</p></div><div style="display:grid;justify-items:end;gap:7px">${statusPill(b.status)}<button class="btn secondary small" data-track="${b.id}">Details</button></div></div>`).join('')||empty('🧭','No rides yet','Your bookings and receipts will appear here.')}</div><div id="rideDetails" class="section-gap"></div>`;document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>showBooking(b.dataset.track));return;}
if(page==='subscription')return renderSubscriptions(main);if(page==='profile')return renderProfile(main);if(page==='safety')return renderSafety(main);if(page==='notifications')return renderNotifications(main);main.innerHTML=head('Page not found','Choose a section from the menu.');}
async function renderDriverPage(){const main=$('#main'),page=state.page,own=await api('/driver/rides').catch(e=>({posts:[],bookings:[],error:e.message})),bookings=await api('/bookings/mine');if(page==='home'||page==='driver'){const available=await api('/rides/available');main.innerHTML=head(page==='home'?`Welcome, ${esc(state.user.name.split(' ')[0])}`:'Available rides','Manage your driving day, respond to requests and keep every journey clear.',`<button class="btn primary" data-page="postRide">＋ Post a route</button>`)+`<div class="grid stats">${stat('Open requests',bookings.filter(b=>b.status==='REQUESTED').length,'↗','Waiting for your response')}${stat('My active rides',bookings.filter(b=>['ACCEPTED','DRIVER_EN_ROUTE','STARTED'].includes(b.status)).length,'⇄','In progress')}${stat('Total earnings',money((await api('/payments/mine')).filter(p=>p.bookingId).reduce((s,p)=>s+p.amount,0)),'₹','Recorded fare payments')}${stat('Driver rating',Number(state.user.ratingAvg||0).toFixed(1)+' ★','☆','Passenger feedback')}</div><div class="grid two"><div class="card"><div class="card-head"><h2>Ride requests for you</h2><span class="pill">${bookings.filter(b=>b.status==='REQUESTED').length} pending</span></div>${bookings.filter(b=>b.status==='REQUESTED').map(b=>`<div class="list-row"><div><b>${esc(b.rider?.name||'Rider')}</b><p>${esc(nodeName(b.pickupNodeId))} → ${esc(nodeName(b.dropNodeId))} · ${money(b.agreedFare)}</p></div><div style="display:flex;gap:6px"><button class="btn success small" data-decision="accept" data-id="${b.id}">Accept</button><button class="btn danger small" data-decision="reject" data-id="${b.id}">Reject</button></div></div>`).join('')||empty('✓','All caught up','New requests appear here.')}</div><div class="card"><div class="card-head"><h2>Available community rides</h2></div>${available.slice(0,3).map(p=>rideCard(p)).join('')||empty('🚗','No other rides','New posted routes appear here.')}</div></div><div class="card section-gap"><div class="card-head"><h2>My route posts</h2><button class="btn primary small" data-page="postRide">Post a route</button></div>${own.posts.map(p=>`<div class="list-row"><div><b>${esc(nodeName(p.originNodeId))} → ${esc(nodeName(p.destNodeId))}</b><p>${dateTime(p.departureTime)} · ${p.seatsAvailable}/${p.seatsTotal} seats left · ${money(p.farePerSeat)} per seat</p></div>${statusPill(p.status)}</div>`).join('')||empty('＋','No routes posted','Post a route to offer empty seats.')}</div>`;wirePageButtons();document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=async()=>{try{await api(`/bookings/${b.dataset.id}/decision`,{method:'POST',body:{decision:b.dataset.decision}});toast('Request updated.');renderPage()}catch(e){toast(e.message)}});return;}
if(page==='postRide'){main.innerHTML=head('Post a route','List your route, departure time, available seats and fare per seat.')+(!state.cache.hasSub?'<div class="alert">An active driver subscription is required. <button class="link-button" data-page="subscription">View plans →</button></div>':'')+`<div class="grid two"><form class="card" id="postRideForm"><div class="form-row"><div class="field"><label>Origin nodal point</label><select name="originNodeId">${state.cache.nodes.map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('')}</select></div><div class="field"><label>Destination nodal point</label><select name="destNodeId">${state.cache.nodes.slice().reverse().map(n=>`<option value="${n.id}" ${n.id==='node-2'?'selected':''}>${esc(n.name)}</option>`).join('')}</select></div></div><div class="field"><label>Departure date & time</label><input type="datetime-local" name="departureTime" min="${dateInput()}" value="${dateInput(new Date(Date.now()+3600000))}" required></div><div class="form-row"><div class="field"><label>Seats offered</label><select name="seatsTotal"><option>1</option><option selected>2</option><option>3</option><option>4</option><option>5</option><option>6</option><option>7</option><option>8</option></select></div><div class="field"><label>Fare per seat (₹)</label><input name="farePerSeat" type="number" min="10" max="1000" value="45" required></div></div><div class="field"><label>Ride type</label><select name="rideType"><option value="POOL">Pool — shared ride</option><option value="SOLO">Solo — private ride</option></select></div><button class="btn primary" ${!state.cache.hasSub?'disabled':''}>Publish route →</button><p class="footer-note">Fare limits are admin-configured. No hidden charges or per-ride commission.</p></form><div class="card"><h2>Before you publish</h2><div class="list-row"><div><b>✓ Verified profile</b><p>Driver documents must be approved.</p></div></div><div class="list-row"><div><b>✓ Active subscription</b><p>Your plan enables ride posting.</p></div></div><div class="list-row"><div><b>✓ Vehicle details</b><p>Add your vehicle on your profile.</p></div></div><div class="alert info">Demo note: maps and navigation are represented by nodal-point routing. Connect a maps provider for turn-by-turn navigation.</div></div></div>`;$('#postRideForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget).entries());body.seatsTotal=Number(body.seatsTotal);body.farePerSeat=Number(body.farePerSeat);try{await api('/driver/rides',{method:'POST',body});toast('Route published!');navigate('home')}catch(err){toast(err.message)}};return;}
if(page==='rides'){main.innerHTML=head('My rides','Accept requests, start trips and complete journeys.')+`<div class="card">${bookings.map(b=>`<div class="list-row"><div><b>${esc(b.rider?.name||'Rider')} · ${esc(nodeName(b.pickupNodeId))} → ${esc(nodeName(b.dropNodeId))}</b><p>${dateTime(b.createdAt)} · ${money(b.agreedFare)} · ${esc(b.vehicle?.number||'')}</p></div><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">${statusPill(b.status)}${b.status==='ACCEPTED'?`<button class="btn primary small" data-status="DRIVER_EN_ROUTE" data-id="${b.id}">Driver en route</button>`:''}${b.status==='DRIVER_EN_ROUTE'?`<button class="btn primary small" data-status="STARTED" data-id="${b.id}">Start trip</button>`:''}${b.status==='STARTED'?`<button class="btn success small" data-status="COMPLETED" data-id="${b.id}">End trip</button>`:''}${['ACCEPTED','DRIVER_EN_ROUTE','STARTED'].includes(b.status)?`<button class="btn secondary small" data-chat="${b.id}">Chat</button>`:''}</div></div>`).join('')||empty('⇄','No assigned rides','Requests you accept will appear here.')}</div><div id="chatPanel" class="section-gap"></div>`;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{await api(`/bookings/${b.dataset.id}/status`,{method:'POST',body:{status:b.dataset.status}});toast('Ride status updated.');renderPage()}catch(e){toast(e.message)}});document.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>renderChat(b.dataset.chat));return;}
if(page==='earnings'){const pays=(await api('/payments/mine')).filter(p=>p.bookingId);const total=pays.reduce((s,p)=>s+p.amount,0);main.innerHTML=head('Earnings','Transparent fare records for completed journeys.')+`<div class="grid stats">${stat('Recorded earnings',money(total),'₹','From fare records')}${stat('Fare records',pays.length,'▤','Cash and demo payments')}${stat('Weekly earnings',money(total),'↗','MVP summary')}${stat('Platform commission',money(0),'✓','No per-ride commission')}</div><div class="card"><h2>Payment records</h2>${pays.map(p=>`<div class="list-row"><div><b>${esc(p.method)} payment</b><p>${dateTime(p.createdAt)} · ${esc(p.reference||'')}</p></div><div><b>${money(p.amount)}</b> ${statusPill(p.status)}</div></div>`).join('')||empty('₹','No earnings yet','Fare payments appear after a completed and paid ride.')}</div>`;return;}
if(page==='ratings'){const ratings=await api(`/ratings/user/${state.user.id}`);main.innerHTML=head('Ratings & feedback','See feedback from the people you travel with.')+`<div class="grid stats">${stat('Average rating',Number(state.user.ratingAvg||0).toFixed(1)+' ★','☆','Your community score')}${stat('Reviews received',ratings.length,'☷','Passenger and rider feedback')}${stat('Verified status',state.user.verifiedStatus,'✓','Profile review status')}${stat('Ride safety','On track','♡','Follow the safety checklist')}</div><div class="card">${ratings.map(r=>`<div class="list-row"><div><b>${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</b><p>${esc(r.comment||'No written feedback')} · ${dateTime(r.createdAt)}</p></div></div>`).join('')||empty('☆','No feedback yet','Ratings appear after rides are completed.')}</div>`;return;}
if(page==='subscription')return renderSubscriptions(main);if(page==='profile')return renderProfile(main);if(page==='safety')return renderSafety(main);if(page==='notifications')return renderNotifications(main);}
async function renderSubscriptions(main){const data=await api('/subscriptions/mine');main.innerHTML=head('Subscriptions','The platform is funded by subscriptions, not ride commissions.')+`<div class="card"><div class="card-head"><h2>Your current plan</h2>${statusPill(data.active?'ACTIVE':'INACTIVE')}</div>${data.subscriptions.filter(s=>s.status==='ACTIVE').map(s=>`<div class="grid two"><div><div class="eyebrow">CURRENT SUBSCRIPTION</div><h2>${esc(s.plan?.name||'Ride Mate plan')}</h2><p>Valid until ${dateTime(s.endAt)}</p></div><div style="text-align:right"><div class="sub-price">${money(s.plan?.price)} <small>/ ${s.plan?.durationDays} days</small></div><p>Payment mode: ${esc(s.paymentMethod||'—')}</p></div></div>`).join('')||'<div class="alert">No active subscription. Select a plan below to unlock ride booking or posting.</div>'}</div><div class="grid three section-gap">${data.plans.map(p=>`<div class="card"><div class="icon-tile">◈</div><h2>${esc(p.name)}</h2><p>${p.role==='rider'?'Book rides and access your ride history.':'Post routes and accept rider requests.'}</p><div class="sub-price">${money(p.price)} <small>/ ${p.durationDays} days</small></div><button class="btn primary" style="width:100%" data-plan="${p.id}">Choose plan →</button></div>`).join('')}</div><div class="alert info section-gap">Payment demo mode: the plan activates locally and a demo payment record is created. Add Razorpay credentials and server-side verification before collecting real money.</div>`;document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=async()=>{try{const d=await api('/subscriptions/purchase',{method:'POST',body:{planId:b.dataset.plan,method:'UPI'}});toast(d.message);renderPage()}catch(e){toast(e.message)}});}
async function renderProfile(main){const d=await api('/me');const user=d.user;main.innerHTML=head('My profile','Manage your personal details, trusted contacts and verification.')+`<div class="grid two"><form class="card" id="profileForm"><div class="card-head"><h2>Personal information</h2>${statusPill(user.verifiedStatus)}</div><div class="field"><label>Full name</label><input name="name" value="${esc(user.name)}" required></div><div class="field"><label>Email</label><input value="${esc(user.email||'')}" disabled></div><div class="field"><label>Phone</label><input value="${esc(user.phone||'')}" disabled></div><div class="field"><label>Profile photo URL (optional)</label><input name="photoUrl" value="${esc(user.photoUrl||'')}" placeholder="https://..."></div><div class="field"><label>Emergency contact name</label><input name="contactName" value="${esc(user.emergencyContacts?.[0]?.name||'')}" placeholder="Trusted person"></div><div class="field"><label>Emergency contact phone</label><input name="contactPhone" value="${esc(user.emergencyContacts?.[0]?.phone||'')}" placeholder="+91..."></div><button class="btn primary">Save profile</button></form><div class="card"><h2>Verification & account</h2><p>Verified users are marked with a badge. Documents are manually reviewed by the Ride Mate admin team.</p><div class="list-row"><div><b>Phone verification</b><p>OTP is demo-only unless SMS is configured.</p></div><button class="btn secondary small" id="otpBtn">Verify phone</button></div><div class="list-row"><div><b>Identity verification</b><p>Upload an ID document for admin review.</p></div>${statusPill(user.verifiedStatus)}</div><form id="identityForm" style="margin-top:15px"><div class="field"><label>Document type</label><select name="type"><option>ID Proof</option><option>Driving Licence</option><option>Vehicle RC</option><option>Insurance</option><option>Profile Photo</option></select></div><div class="field"><label>Document file (PDF/JPG/PNG, max 8 MB)</label><input name="documents" type="file" accept=".pdf,.png,.jpg,.jpeg" required></div><button class="btn secondary">Submit for review</button></form>${user.role==='driver'?`<div class="separator"></div><h2>Vehicle details</h2><form id="vehicleForm"><div class="field"><label>Registration number</label><input name="number" placeholder="GJ 16 AB 1234" required></div><div class="field"><label>Vehicle model</label><input name="model" placeholder="Car make and model" required></div><div class="field"><label>Seats offered</label><input name="seats" type="number" min="1" max="8" value="3" required></div><button class="btn secondary">Save vehicle</button></form>`:''}</div></div>`;$('#profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const userData={name:f.get('name'),photoUrl:f.get('photoUrl'),emergencyContacts:f.get('contactPhone')?[{name:f.get('contactName')||'Emergency Contact',phone:f.get('contactPhone')}]:[]};const r=await api('/me',{method:'PATCH',body:userData});state.user=r.user;localStorage.setItem('rm_user',JSON.stringify(r.user));toast('Profile saved.');renderPage()}catch(e){toast(e.message)}};$('#otpBtn').onclick=async()=>{try{const r=await api('/auth/request-otp',{method:'POST',body:{}});const code=prompt(r.message+(r.demoCode?` Demo code: ${r.demoCode}`:'' )+'\nEnter the OTP:');if(code){const v=await api('/auth/verify-otp',{method:'POST',body:{code}});toast(v.message)}}catch(e){toast(e.message)}};$('#identityForm').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.currentTarget);const endpoint=state.user.role==='driver'?'/api/driver/documents':'/api/verification/documents';if(state.user.role==='driver')fd.set('types',fd.get('type'));const res=await fetch(endpoint,{method:'POST',headers:{Authorization:'Bearer '+state.token},body:fd});const r=await res.json();if(!res.ok)throw Error(r.error);toast(r.message);renderPage()}catch(e){toast(e.message)}};if($('#vehicleForm'))$('#vehicleForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));f.seats=Number(f.seats);try{await api('/driver/vehicle',{method:'POST',body:f});toast('Vehicle details saved.')}catch(e){toast(e.message)}};}
async function renderSafety(main){const d=await api('/safety/tips');main.innerHTML=head('Safety & emergency help','Your safety matters. Meet at a nodal point and verify every ride.')+`<div class="grid two"><div class="card"><div class="card-head"><h2>Safety checklist</h2><span class="pill green">Stay aware</span></div>${d.tips.map((t,i)=>`<div class="list-row"><div style="display:flex;gap:12px;align-items:center"><div class="avatar">${i+1}</div><div>${esc(t)}</div></div></div>`).join('')}<div class="separator"></div><button class="btn danger" id="sosBtn">⚠ Emergency SOS</button> <a class="btn secondary" href="tel:112">Call 112</a><p class="footer-note">SOS creates an alert for the Trust & Safety console. This demo cannot guarantee live dispatch, SMS or emergency response.</p></div><div class="card"><h2>Contact Trust & Safety</h2><p>Report a safety concern, payment issue or problem with another user.</p><form id="supportForm"><div class="field"><label>Category</label><select name="category"><option>Safety concern</option><option>Payment dispute</option><option>Ride issue</option><option>Account support</option><option>Other</option></select></div><div class="field"><label>Tell us what happened</label><textarea name="description" required placeholder="Include useful details, but do not share passwords or payment PINs."></textarea></div><button class="btn primary">Send support request</button></form><div class="separator"></div><div class="list-row"><div><b>Emergency services (India)</b><p>112 · use when immediate help is needed.</p></div><a class="btn secondary small" href="tel:112">Call</a></div><div class="list-row"><div><b>Trust & Safety</b><p>${esc(d.trustSafetyEmail)}</p></div></div></div></div>`;$('#sosBtn').onclick=async()=>{if(!confirm('Send an SOS alert to the Ride Mate Trust & Safety console? If you are in immediate danger, call 112.'))return;try{const b=await api('/bookings/mine');const active=b.find(x=>['ACCEPTED','DRIVER_EN_ROUTE','STARTED'].includes(x.status));let coords={};if(navigator.geolocation){try{coords=await new Promise(resolve=>navigator.geolocation.getCurrentPosition(pos=>resolve({lat:pos.coords.latitude,lng:pos.coords.longitude}),()=>resolve({}),{timeout:3500,maximumAge:5000}));}catch{}}const r=await api('/sos',{method:'POST',body:{bookingId:active?.id,note:'SOS initiated from Safety screen',...coords}});alert(r.message+'\nEmergency services: 112');}catch(e){toast(e.message)}};$('#supportForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{await api('/support',{method:'POST',body});toast('Support request sent.');e.currentTarget.reset()}catch(e){toast(e.message)}};}
async function renderNotifications(main){const ns=await api('/notifications');main.innerHTML=head('Notifications','Ride updates, subscription reminders and safety messages.')+`<div class="card">${ns.map(n=>`<div class="list-row"><div><b>${esc(n.message)}</b><p>${dateTime(n.createdAt)} · ${esc(n.type)}</p></div>${n.read?'<span class="pill">Read</span>':`<button class="btn secondary small" data-read="${n.id}">Mark read</button>`}</div>`).join('')||empty('♧','You’re all caught up','New ride and account updates appear here.')}</div>`;document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{await api('/notifications/'+b.dataset.read+'/read',{method:'PATCH',body:{}});renderPage()});}
async function showBooking(id){const d=await api('/bookings/'+id);const b=d.booking;$('#rideDetails').innerHTML=`<div class="card"><div class="card-head"><h2>Ride details</h2>${statusPill(b.status)}</div><div class="grid two"><div><p><b>Route</b><br>${esc(nodeName(b.pickupNodeId))} → ${esc(nodeName(b.dropNodeId))}</p><p><b>Driver</b><br>${esc(b.driver?.name||'—')} · ★ ${Number(b.driver?.ratingAvg||0).toFixed(1)}</p><p><b>Vehicle</b><br>${esc(b.vehicle?.model||'—')} · ${esc(b.vehicle?.number||'—')}</p><p><b>Fare</b><br>${money(b.agreedFare)} per seat</p></div><div><div class="map-panel"><div class="map-inner"><b>Ride tracking</b><p>Live GPS requires location permissions and a maps provider.</p><div class="map-pin">📍<div><b>${esc(nodeName(b.pickupNodeId))}</b><small>Pickup nodal point</small></div></div><div class="map-pin">🏁<div><b>${esc(nodeName(b.dropNodeId))}</b><small>Drop-off nodal point</small></div></div></div></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">${['REQUESTED','ACCEPTED','DRIVER_EN_ROUTE','STARTED'].includes(b.status)?`<button class="btn danger small" id="cancelBooking">Cancel ride</button>`:''}${['ACCEPTED','DRIVER_EN_ROUTE','STARTED'].includes(b.status)?`<button class="btn secondary small" id="chatOpen">Message</button><button class="btn secondary small" id="callDriver">Call</button><button class="btn secondary small" id="shareRide">Share trip</button><button class="btn secondary small" id="updateLocation">Update my location</button>`:''}${b.status==='COMPLETED'&&b.paymentStatus!=='PAID'?`<button class="btn primary small" id="payRide">Record payment</button>`:''}${b.status==='COMPLETED'?`<button class="btn soft small" id="rateRide">Rate ride</button>`:''}</div></div></div><div id="rideActionPanel"></div></div>`;if($('#cancelBooking'))$('#cancelBooking').onclick=async()=>{const reason=prompt('Why are you cancelling?','Change of plans');if(reason===null)return;try{await api(`/bookings/${id}/cancel`,{method:'POST',body:{reason}});toast('Ride cancelled.');renderPage()}catch(e){toast(e.message)}};if($('#chatOpen'))$('#chatOpen').onclick=()=>renderChat(id);if($('#callDriver'))$('#callDriver').onclick=()=>{if(b.driver?.phone)location.href='tel:'+b.driver.phone;else toast('Driver phone number is unavailable.')};if($('#shareRide'))$('#shareRide').onclick=async()=>{try{const r=await api(`/bookings/${id}/share-link`,{method:'POST',body:{}});if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(r.url);toast('Trip share link copied. Share it only with a trusted contact.')}else prompt('Copy this trip share link',r.url)}catch(e){toast(e.message)}};if($('#updateLocation'))$('#updateLocation').onclick=()=>{if(!navigator.geolocation){toast('This browser does not support geolocation.');return;}navigator.geolocation.getCurrentPosition(async pos=>{try{await api(`/bookings/${id}/location`,{method:'POST',body:{lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy}});toast('Your latest location was shared with ride participants.')}catch(e){toast(e.message)}},()=>toast('Location permission was denied or unavailable.'),{enableHighAccuracy:true,timeout:8000,maximumAge:0})};if($('#payRide'))$('#payRide').onclick=async()=>{const method=prompt('Payment method: CASH, UPI or CARD','UPI');if(!method)return;try{const r=await api(`/bookings/${id}/payment`,{method:'POST',body:{method:method.toUpperCase()}});toast(r.message);showBooking(id)}catch(e){toast(e.message)}};if($('#rateRide'))$('#rateRide').onclick=()=>renderRating(id);}
async function renderChat(id){const p=$('#rideActionPanel')||$('#chatPanel')||$('#rideDetails');p.innerHTML=`<div class="card"><div class="card-head"><h2>Ride chat</h2><button class="btn secondary small" id="refreshChat">Refresh</button></div><div class="chat-box" id="chatBox">Loading messages…</div><form class="chat-compose" id="chatForm"><input name="text" maxlength="1000" placeholder="Message the other traveller…" required><button class="btn primary">Send</button></form></div>`;const load=async()=>{const msgs=await api('/messages/'+id);$('#chatBox').innerHTML=msgs.map(m=>`<div class="bubble ${m.senderId===state.user.id?'mine':''}">${esc(m.text)}<small>${m.senderId===state.user.id?'You':'Ride participant'} · ${dateTime(m.sentAt)}</small></div>`).join('')||'<div class="empty">No messages yet.</div>';$('#chatBox').scrollTop=$('#chatBox').scrollHeight;};await load();$('#refreshChat').onclick=load;$('#chatForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/messages/'+id,{method:'POST',body:{text:f.get('text')}});e.currentTarget.reset();load()}catch(e){toast(e.message)}};}
async function renderRating(id){const p=$('#rideActionPanel')||$('#rideDetails');p.innerHTML=`<div class="card"><h2>Rate your ride</h2><p>Help the community travel better.</p><div class="stars">${[1,2,3,4,5].map(n=>`<button class="star ${n<=state.rating?'selected':''}" data-star="${n}">★</button>`).join('')}</div><form id="ratingForm"><div class="field" style="margin-top:12px"><label>Feedback (optional)</label><textarea name="comment" maxlength="1000" placeholder="What went well?"></textarea></div><button class="btn primary">Submit rating</button></form></div>`;document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{state.rating=Number(b.dataset.star);renderRating(id)});$('#ratingForm').onsubmit=async e=>{e.preventDefault();try{await api('/ratings',{method:'POST',body:{bookingId:id,stars:state.rating,comment:new FormData(e.currentTarget).get('comment')}});toast('Thank you for your feedback.');renderPage()}catch(e){toast(e.message)}};}
async function renderAdminPage(){const main=$('#main'),page=state.page;const overview=await api('/admin/overview');if(page==='home'){main.innerHTML=head('Admin overview','Monitor Ride Mate operations, verification and safety.')+`<div class="grid stats">${stat('Total users',overview.users,'♙','Riders and drivers')}${stat('Active rides',overview.activeRides,'⇄','Currently in progress')}${stat('Pending verification',overview.pendingVerification,'✓','Needs manual review')}${stat('Open SOS alerts',overview.openSOS,'⚠','Trust & Safety queue')}</div><div class="grid two"><div class="card"><div class="card-head"><h2>Operations snapshot</h2><button class="link-button" data-page="reports">Full report →</button></div><div class="list-row"><span>Completed rides</span><b>${overview.completedRides}</b></div><div class="list-row"><span>Open support tickets</span><b>${overview.openTickets}</b></div><div class="list-row"><span>Subscription revenue (demo records)</span><b>${money(overview.subscriptionRevenue)}</b></div><div class="list-row"><span>Estimated CO₂ saved</span><b>${overview.estimatedCo2SavedKg} kg</b></div></div><div class="card"><div class="card-head"><h2>Trust & Safety actions</h2></div><div class="list-row"><div><b>Driver & identity reviews</b><p>Approve only after checking submitted documents.</p></div><button class="btn secondary small" data-page="verify">Review</button></div><div class="list-row"><div><b>SOS console</b><p>Review emergency events and update status.</p></div><button class="btn danger small" data-page="sos">Open console</button></div><div class="list-row"><div><b>Support tickets</b><p>Respond to user issues and disputes.</p></div><button class="btn secondary small" data-page="support">View tickets</button></div></div></div>`;wirePageButtons();return;}
if(page==='users'){const users=await api('/admin/users');main.innerHTML=head('User management','Review accounts and apply account restrictions.')+`<div class="card"><div class="card-head"><h2>Registered users</h2><span class="pill">${users.length} accounts</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Email / Phone</th><th>Verification</th><th>Rating</th><th>Account</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.name)}</b><br><small>${esc(u.id)}</small></td><td>${esc(u.role)}</td><td>${esc(u.email||u.phone)}</td><td>${statusPill(u.verifiedStatus)}</td><td>★ ${Number(u.ratingAvg||0).toFixed(1)}</td><td>${u.blocked?statusPill('BLOCKED'):statusPill('ACTIVE')}</td><td><button class="btn ${u.blocked?'success':'danger'} small" data-block="${u.id}" data-value="${!u.blocked}">${u.blocked?'Unblock':'Block'}</button></td></tr>`).join('')}</tbody></table></div></div>`;document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{try{await api('/admin/users/'+b.dataset.block,{method:'PATCH',body:{blocked:b.dataset.value==='true'}});toast('User updated.');renderPage()}catch(e){toast(e.message)}});return;}
if(page==='verify'){const list=await api('/admin/verifications');main.innerHTML=head('Verification centre','Manually review driver documents and passenger identity submissions.')+`<div class="card">${list.map(v=>`<div class="list-row"><div><b>${esc(v.user?.name||v.userId)}</b><p>${esc(v.user?.role||'user')} · ${v.documents?.length||0} document(s) · Background check: ${esc(v.backgroundCheckStatus||'Pending')}</p><p>${(v.documents||[]).map(x=>esc(x.type)+' ('+esc(x.status)+')').join(' · ')||'No document metadata available'}</p></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn success small" data-verify="${v.userId}" data-status="approved">Approve</button><button class="btn danger small" data-verify="${v.userId}" data-status="rejected">Reject</button><button class="btn secondary small" data-verify="${v.userId}" data-status="pending">Pending</button></div></div>`).join('')||empty('✓','No pending verification','Submitted documents will appear here.')}</div>`;document.querySelectorAll('[data-verify]').forEach(b=>b.onclick=async()=>{try{await api('/admin/verifications/'+b.dataset.verify,{method:'POST',body:{status:b.dataset.status}});toast('Verification updated.');renderPage()}catch(e){toast(e.message)}});return;}
if(page==='rides'){const r=await api('/admin/rides');main.innerHTML=head('Ride monitoring','Inspect route posts and ride lifecycle status.')+`<div class="card"><h2>Bookings</h2><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Rider</th><th>Driver</th><th>Route</th><th>Fare</th><th>Status</th><th>Created</th></tr></thead><tbody>${r.bookings.map(b=>`<tr><td>${esc(b.id)}</td><td>${esc(b.rider?.name||'—')}</td><td>${esc(b.driver?.name||'—')}</td><td>${esc(nodeName(b.pickupNodeId))} → ${esc(nodeName(b.dropNodeId))}</td><td>${money(b.agreedFare)}</td><td>${statusPill(b.status)}</td><td>${dateTime(b.createdAt)}</td></tr>`).join('')}</tbody></table></div><div class="separator"></div><h2>Posted routes</h2>${r.posts.map(p=>`<div class="list-row"><div><b>${esc(nodeName(p.originNodeId))} → ${esc(nodeName(p.destNodeId))}</b><p>${dateTime(p.departureTime)} · ${p.seatsAvailable}/${p.seatsTotal} seats · ${money(p.farePerSeat)}</p></div>${statusPill(p.status)}</div>`).join('')}</div>`;return;}
if(page==='nodes'){const nodes=await api('/admin/nodal-points');const settings=await api('/admin/settings');main.innerHTML=head('Nodal point management','Manage fixed pick-up/drop-off hubs and fare guardrails.')+`<div class="grid two"><div class="card"><h2>Add nodal point</h2><form id="nodeForm"><div class="field"><label>Name</label><input name="name" required placeholder="e.g. College Gate"></div><div class="form-row"><div class="field"><label>Latitude</label><input name="lat" type="number" step="any" required value="21.7057"></div><div class="field"><label>Longitude</label><input name="lng" type="number" step="any" required value="72.9959"></div></div><div class="field"><label>City</label><input name="city" value="Bharuch" required></div><button class="btn primary">Add point</button></form><div class="separator"></div><h2>Fare limits</h2><form id="fareForm"><div class="form-row"><div class="field"><label>Minimum fare (₹)</label><input name="min" type="number" min="0" value="${settings.fareConfig.min}" required></div><div class="field"><label>Maximum fare (₹)</label><input name="max" type="number" min="1" value="${settings.fareConfig.max}" required></div></div><button class="btn secondary">Save fare guardrails</button></form></div><div class="card"><h2>Active and disabled hubs</h2>${nodes.map(n=>`<div class="list-row"><div><b>${esc(n.name)}</b><p>${n.lat}, ${n.lng} · ${esc(n.city)}</p></div><button class="btn ${n.isActive?'danger':'success'} small" data-node="${n.id}" data-active="${!n.isActive}">${n.isActive?'Disable':'Enable'}</button></div>`).join('')}</div></div>`;$('#nodeForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));f.lat=Number(f.lat);f.lng=Number(f.lng);try{await api('/admin/nodal-points',{method:'POST',body:f});toast('Nodal point added.');renderPage()}catch(e){toast(e.message)}};$('#fareForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));f.min=Number(f.min);f.max=Number(f.max);try{await api('/admin/fare-config',{method:'PATCH',body:f});toast('Fare limits saved.')}catch(e){toast(e.message)}};document.querySelectorAll('[data-node]').forEach(b=>b.onclick=async()=>{try{await api('/admin/nodal-points/'+b.dataset.node,{method:'PATCH',body:{isActive:b.dataset.active==='true'}});renderPage()}catch(e){toast(e.message)}});return;}
if(page==='payments'){const ps=await api('/admin/payments');main.innerHTML=head('Payments','Review demo fare and subscription payment records.')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Record</th><th>Type</th><th>Method</th><th>Amount</th><th>Status</th><th>Reference</th><th>Date</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${esc(p.id)}</td><td>${p.subscriptionId?'Subscription':'Ride fare'}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td>${statusPill(p.status)}</td><td>${esc(p.reference||'—')}</td><td>${dateTime(p.createdAt)}</td></tr>`).join('')}</tbody></table></div></div>`;return;}
if(page==='support'){const ts=await api('/admin/support');main.innerHTML=head('Support & disputes','Assign status to support requests, safety concerns and payment disputes.')+`<div class="card">${ts.map(t=>`<div class="list-row"><div><b>${esc(t.category)}</b><p>${esc(t.description)}</p><p>${esc(t.userId)} · ${dateTime(t.createdAt)}</p></div><div style="display:flex;gap:6px;align-items:center"><select class="control" data-ticket-status="${t.id}" style="width:135px"><option ${t.status==='OPEN'?'selected':''}>OPEN</option><option ${t.status==='IN_PROGRESS'?'selected':''}>IN_PROGRESS</option><option ${t.status==='RESOLVED'?'selected':''}>RESOLVED</option><option ${t.status==='REJECTED'?'selected':''}>REJECTED</option></select><button class="btn primary small" data-ticket="${t.id}">Save</button></div></div>`).join('')||empty('☏','No support tickets','New user requests appear here.')}</div>`;document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=async()=>{const id=b.dataset.ticket;try{await api('/admin/support/'+id,{method:'PATCH',body:{status:$(`[data-ticket-status="${id}"]`).value}});toast('Ticket updated.');renderPage()}catch(e){toast(e.message)}});return;}
if(page==='sos'){const events=await api('/admin/sos');main.innerHTML=head('SOS alert console','Urgent safety events are recorded here for Trust & Safety review.')+`<div class="alert danger">This demo console does not dispatch emergency services automatically. Use established emergency channels for immediate danger.</div><div class="card">${events.map(e=>`<div class="list-row"><div><b>⚠ ${esc(e.user?.name||e.userId)}</b><p>${dateTime(e.createdAt)} · ${esc(e.note||'SOS alert')}</p><p>Location: ${e.location?.lat??'unknown'}, ${e.location?.lng??'unknown'} · Booking: ${esc(e.bookingId||'—')}</p></div><div style="display:flex;gap:6px;align-items:center">${statusPill(e.status)}${e.status!=='RESOLVED'?`<button class="btn success small" data-sos="${e.id}">Resolve</button>`:''}</div></div>`).join('')||empty('♡','No SOS alerts','New emergency events will appear here.')}</div>`;document.querySelectorAll('[data-sos]').forEach(b=>b.onclick=async()=>{try{await api('/admin/sos/'+b.dataset.sos,{method:'PATCH',body:{status:'RESOLVED'}});renderPage()}catch(e){toast(e.message)}});return;}
if(page==='reports'){const r=await api('/admin/reports'),o=r.overview;main.innerHTML=head('Reports & analytics','Operational metrics for the Bharuch pilot. CO₂ values are illustrative estimates.')+`<div class="grid stats">${stat('Registered users',o.users,'♙','All roles')}${stat('Ride posts',o.ridesPosted,'⇄','Driver routes')}${stat('Completed rides',o.completed,'✓','Successful trips')}${stat('Active subscriptions',o.subscriptions,'◈','Unexpired plans')}</div><div class="grid two"><div class="card"><h2>Key metrics</h2><div class="list-row"><span>All bookings</span><b>${o.bookings}</b></div><div class="list-row"><span>Cancelled bookings</span><b>${o.cancelled}</b></div><div class="list-row"><span>Subscription revenue (recorded)</span><b>${money(o.subscriptionRevenueINR)}</b></div><div class="list-row"><span>Estimated CO₂ saved</span><b>${o.estimatedCo2SavedKg} kg</b></div><div class="list-row"><span>Average rating</span><b>${o.averageRating||'—'} ★</b></div></div><div class="card"><h2>Recent audit activity</h2>${r.recentAudit.slice(0,12).map(a=>`<div class="list-row"><div><b>${esc(a.action)}</b><p>${dateTime(a.createdAt)} · ${esc(a.actorId)}</p></div></div>`).join('')||empty('▤','No audit entries','Admin and safety actions are logged here.')}</div></div>`;return;}
main.innerHTML=head('Admin console','Choose a section from the navigation.');}
function wirePageButtons(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-book]').forEach(b=>b.onclick=async()=>{if(!state.cache.hasSub){toast('Subscribe before booking a ride.');navigate('subscription');return;}if(!confirm('Request this ride at the displayed fare per seat?'))return;try{const p=await api('/rides/available');const post=p.find(x=>x.id===b.dataset.book);if(!post)throw Error('This ride is no longer available.');const r=await api('/bookings',{method:'POST',body:{ridePostId:post.id,pickupNodeId:post.originNodeId,dropNodeId:post.destNodeId,rideType:state.rideType||'POOL'}});toast(r.message);navigate('rides')}catch(e){toast(e.message)}});}
async function renderApp(){if(!state.token||!state.user){renderAuth();return;}try{const me=await api('/me');state.user=me.user;localStorage.setItem('rm_user',JSON.stringify(state.user));}catch{logout();return;}renderShell();renderPage();}
async function renderSharedTrip(){const token=decodeURIComponent(location.pathname.split('/').pop()||'');$('#app').innerHTML='<main class="main" style="max-width:760px;margin:8vh auto"><div class="card">Loading shared trip…</div></main>';try{const r=await fetch('/api/share/'+encodeURIComponent(token));const d=await r.json();if(!r.ok)throw Error(d.error||'Share link unavailable.');$('#app').innerHTML=`<main class="main" style="max-width:760px;margin:6vh auto"><div class="brand"><div class="brand-mark">R</div><div>Ride Mate<small>TRUSTED TRIP SHARING</small></div></div><div style="height:22px"></div><div class="card"><div class="eyebrow">LIVE TRIP SHARE</div><h1 style="font-family:Manrope">${esc(d.driver?.name||'Ride')} is on a trip</h1><p>Current status: ${statusPill(d.status)}</p><div class="map-panel"><div class="map-inner"><div class="map-pin">📍<div><b>${esc(d.pickup?.name||'Pickup')}</b><small>Pickup point</small></div></div><div class="map-pin">🏁<div><b>${esc(d.drop?.name||'Drop-off')}</b><small>Destination point</small></div></div>${d.location?`<div class="map-pin">🛰️<div><b>Latest shared location</b><small>${d.location.lat}, ${d.location.lng}</small><small>Updated ${dateTime(d.location.updatedAt)}</small></div></div>`:'<p>Location has not been shared yet.</p>'}</div></div><div class="list-row"><div><b>${esc(d.vehicle?.model||'Vehicle')}</b><p>${esc(d.vehicle?.number||'Registration unavailable')}</p></div></div><div class="alert info">This link shows the latest location shared by a ride participant. If immediate help is needed, call 112.</div></div></main>`;}catch(e){$('#app').innerHTML=`<main class="main" style="max-width:760px;margin:8vh auto"><div class="card"><h1>Trip link unavailable</h1><p>${esc(e.message)}</p></div></main>`;}}
window.addEventListener('DOMContentLoaded',()=>location.pathname.startsWith('/share/')?renderSharedTrip():renderApp());
